package io.warrant.core.secrets;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Pattern;

/**
 * Development secret store: one file per secret under a directory that is git-ignored and generated by
 * {@code scripts/dev-bootstrap.sh}. Refuses anything that is not a plain {@code local-secret://name} reference.
 */
public final class LocalSecretStore implements SecretResolver {

    public static final String SCHEME = "local-secret://";
    private static final Pattern NAME = Pattern.compile("^[a-z0-9][a-z0-9_-]{0,63}$");

    private final Path directory;

    public LocalSecretStore(Path directory) {
        this.directory = directory.toAbsolutePath().normalize();
    }

    @Override
    public SecretValue resolve(String reference) {
        if (reference == null || !reference.startsWith(SCHEME)) {
            throw new SecretUnavailableException(String.valueOf(reference), "not a local-secret reference");
        }
        String name = reference.substring(SCHEME.length());
        if (!NAME.matcher(name).matches()) {
            throw new SecretUnavailableException(reference, "invalid secret name");
        }
        Path file = directory.resolve(name).normalize();
        if (!file.startsWith(directory)) {
            throw new SecretUnavailableException(reference, "path escapes the secret directory");
        }
        try {
            return new SecretValue(Files.readAllBytes(file));
        } catch (IOException e) {
            throw new SecretUnavailableException(reference, "not readable");
        }
    }
}
